# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">GÜNLÜK YAŞAMDA SÜRTÜNME KUVVETİNİ ARTIRMA VE AZALTMA (FB.5.2.4)</text>\n  <rect x="20" y="46" width="320" height="194" rx="8" fill="#f0fdf4" stroke="#16a34a" stroke-width="1.5"/>\n  <text x="180" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Sürtünmeyi Artırma Uygulamaları</text>\n  <text x="180" y="98" text-anchor="middle" font-size="11.5" fill="#14532d">• Kış lastiği ve kar zinciri takılması (kaymayı önler)</text>\n  <text x="180" y="124" text-anchor="middle" font-size="11.5" fill="#14532d">• Buzlu yollara kum, talaş ve tuz serpilmesi</text>\n  <text x="180" y="150" text-anchor="middle" font-size="11.5" fill="#14532d">• Futbolcu ve dağcı ayakkabılarının dişli/çivili olması</text>\n  <text x="180" y="176" text-anchor="middle" font-size="11.5" fill="#14532d">• Kaleci eldiveni ve haltercilerin ellerine toz sürmesi</text>\n  <text x="180" y="202" text-anchor="middle" font-size="11.5" fill="#14532d">• Geniş yüzeyli paraşüt ile hava direncinin artırılması</text>\n  <text x="180" y="226" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">Amaç: Güvenli tutunma, yürüme ve güvenli yavaşlama</text>\n\n  <rect x="360" y="46" width="320" height="194" rx="8" fill="#eff6ff" stroke="#2563eb" stroke-width="1.5"/>\n  <text x="520" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Sürtünmeyi Azaltma Uygulamaları</text>\n  <text x="520" y="98" text-anchor="middle" font-size="11.5" fill="#1e3a8a">• Kapı menteşeleri ve motor parçalarının yağlanması</text>\n  <text x="520" y="124" text-anchor="middle" font-size="11.5" fill="#1e3a8a">• Bavul, market arabası ve patenlere tekerlek takılması</text>\n  <text x="520" y="150" text-anchor="middle" font-size="11.5" fill="#1e3a8a">• Dönen millerde bilye (rulman) kullanılması</text>\n  <text x="520" y="176" text-anchor="middle" font-size="11.5" fill="#1e3a8a">• Hızlı tren, uçak ve gemilerin burnunun sivri (V) yapılması</text>\n  <text x="520" y="202" text-anchor="middle" font-size="11.5" fill="#1e3a8a">• Kayakçı ve yüzücülerin özel kaygan giysiler giymesi</text>\n  <text x="520" y="226" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">Amaç: Kolay hareket, enerji tasarrufu ve aşınmayı önleme</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">2. ÜNİTE ÖZETİ: KUVVET, KÜTLE, AĞIRLIK VE SÜRTÜNME</text>\n  <rect x="20" y="48" width="210" height="190" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="1.5"/>\n  <text x="125" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#b45309">Kuvvetin Ölçülmesi</text>\n  <text x="125" y="102" text-anchor="middle" font-size="11.5" fill="#78350f">• Ölçüm aracı: Dinamometre</text>\n  <text x="125" y="128" text-anchor="middle" font-size="11.5" fill="#78350f">• Birimi: Newton (N)</text>\n  <text x="125" y="154" text-anchor="middle" font-size="11.5" fill="#78350f">• Esnek yayın uzama özelliğine</text>\n  <text x="125" y="174" text-anchor="middle" font-size="11.5" fill="#78350f">dayanır (ince yay hassas ölçer).</text>\n  <text x="125" y="210" text-anchor="middle" font-size="11" font-weight="bold" fill="#b45309">Kuvvet 2 katına çıkarsa uzama 2 kat olur.</text>\n\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#fdf2f8" stroke="#db2777" stroke-width="1.5"/>\n  <text x="350" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">Kütle ve Ağırlık Farkı</text>\n  <text x="350" y="102" text-anchor="middle" font-size="11.5" fill="#831843">• Kütle: Değişmeyen madde miktarı</text>\n  <text x="350" y="124" text-anchor="middle" font-size="11.5" fill="#831843">(Eşit kollu terazi · kg / g)</text>\n  <text x="350" y="152" text-anchor="middle" font-size="11.5" fill="#831843">• Ağırlık: Kütleye etki eden yer</text>\n  <text x="350" y="174" text-anchor="middle" font-size="11.5" fill="#831843">çekimi kuvveti (Dinamometre · N)</text>\n  <text x="350" y="210" text-anchor="middle" font-size="11" font-weight="bold" fill="#be185d">Ay\'daki ağırlık Dünya\'dakinin 6\'da 1\'idir.</text>\n\n  <rect x="470" y="48" width="210" height="190" rx="8" fill="#ecfeff" stroke="#0891b2" stroke-width="1.5"/>\n  <text x="575" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">Sürtünme Kuvveti</text>\n  <text x="575" y="102" text-anchor="middle" font-size="11.5" fill="#155e75">• Pürüzlü yüzeyde sürtünme BÜYÜK</text>\n  <text x="575" y="128" text-anchor="middle" font-size="11.5" fill="#155e75">• Kaygan yüzeyde sürtünme KÜÇÜK</text>\n  <text x="575" y="154" text-anchor="middle" font-size="11.5" fill="#155e75">• Hava ve su ortamı da cisimlere</text>\n  <text x="575" y="174" text-anchor="middle" font-size="11.5" fill="#155e75">direnç (sürtünme) uygular.</text>\n  <text x="575" y="210" text-anchor="middle" font-size="11" font-weight="bold" fill="#0e7490">Yüzey alanı büyüdükçe direnç artar.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">3. ÜNİTEYE GİRİŞ: HÜCRE VE TEMEL KISIMLARI (FB.5.3.1)</text>\n  <rect x="25" y="48" width="310" height="190" rx="8" fill="#f0fdf4" stroke="#16a34a" stroke-width="1.5"/>\n  <text x="180" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Bitki Hücresi (Köşeli Yapı)</text>\n  <rect x="85" y="88" width="190" height="92" rx="6" fill="#bbf7d0" stroke="#15803d" stroke-width="3"/>\n  <rect x="97" y="98" width="166" height="72" rx="4" fill="#dcfce7" stroke="#22c55e" stroke-width="1.5" stroke-dasharray="4,2"/>\n  <circle cx="180" cy="134" r="18" fill="#166534"/>\n  <text x="180" y="138" text-anchor="middle" font-size="10" font-weight="bold" fill="#ffffff">Çekirdek</text>\n  <text x="180" y="200" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#14532d">• Hücre duvarı (çeperi) ve kloroplast VARDIR.</text>\n  <text x="180" y="220" text-anchor="middle" font-size="11.5" fill="#166534">• Kofulları büyük ve az sayıdadır.</text>\n\n  <rect x="365" y="48" width="310" height="190" rx="8" fill="#eff6ff" stroke="#2563eb" stroke-width="1.5"/>\n  <text x="520" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Hayvan Hücresi (Yuvarlak/Oval Yapı)</text>\n  <ellipse cx="520" cy="134" rx="88" ry="44" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <circle cx="520" cy="134" r="18" fill="#1e40af"/>\n  <text x="520" y="138" text-anchor="middle" font-size="10" font-weight="bold" fill="#ffffff">Çekirdek</text>\n  <text x="520" y="200" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e3a8a">• Hücre duvarı ve kloroplast YOKTUR; sentrozom vardır.</text>\n  <text x="520" y="220" text-anchor="middle" font-size="11.5" fill="#1e3a8a">• Ortak 3 kısım: Hücre zarı, Sitoplazma, Çekirdek</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
